// Node: Processar e Cruzar Dados (RPA + Catálogo de Investimentos)
const webhookData = $('Webhook Clientes (RPA Trigger)').first().json;
const csvRaw = $('HTTP Request - Baixar data.csv').first().json.data || $('HTTP Request - Baixar data.csv').first().data;

// Fallback de catálogo caso a requisição HTTP retorne texto cru
let produtos = [];
if (typeof csvRaw === 'string') {
  const linhas = csvRaw.trim().split('\n');
  const headers = linhas[0].split(',').map(h => h.trim());
  for (let i = 1; i < linhas.length; i++) {
    const vals = linhas[i].split(',').map(v => v.trim());
    if (vals.length >= 4) {
      produtos.push({
        perfil: vals[0],
        produto: vals[1],
        minimo: parseFloat(vals[2]) || 0,
        rentabilidade: vals[3]
      });
    }
  }
} else {
  // Catálogo padrão embutido como fallback de resiliência
  produtos = [
    { perfil: "Conservador", produto: "Poupança", minimo: 100, rentabilidade: "6.2%" },
    { perfil: "Conservador", produto: "CDB Liquidez Diária", minimo: 1000, rentabilidade: "12.5%" },
    { perfil: "Conservador", produto: "Tesouro Selic", minimo: 500, rentabilidade: "13.0%" },
    { perfil: "Moderado", produto: "CDB Prefixado", minimo: 1000, rentabilidade: "14.0%" },
    { perfil: "Moderado", produto: "Fundo Multimercado", minimo: 5000, rentabilidade: "16.0%" },
    { perfil: "Moderado", produto: "Tesouro IPCA+", minimo: 1000, rentabilidade: "IPCA+6.0%" },
    { perfil: "Arrojado", produto: "Ações ETF", minimo: 500, rentabilidade: "Variável" },
    { perfil: "Arrojado", produto: "Fundo de Ações", minimo: 10000, rentabilidade: "Variável" },
    { perfil: "Arrojado", produto: "Criptomoedas", minimo: 100, rentabilidade: "Variável" }
  ];
}

const clientes = webhookData.body?.clientes || webhookData.clientes || [
  { id: 1, nome: "Ana Silva", email: "ana@email.com", saldo_formatado: "R$ 12.500,00", saldo: 12500, perfil: "Conservador" },
  { id: 2, nome: "Bruno Lima", email: "bruno@email.com", saldo_formatado: "R$ 3.200,00", saldo: 3200, perfil: "Moderado" },
  { id: 3, nome: "Carla Souza", email: "carla@email.com", saldo_formatado: "R$ 28.900,00", saldo: 28900, perfil: "Arrojado" }
];

const resultados = [];

for (const cliente of clientes) {
  // Casar investimentos por perfil de risco e limite de saldo mínimo
  const produtosCompativeis = produtos.filter(p => {
    const perfilMatch = p.perfil.toLowerCase() === cliente.perfil.toLowerCase();
    const saldoPermite = cliente.saldo >= p.minimo;
    return perfilMatch && saldoPermite;
  });

  const promptLLM = `Você é um Consultor de Investimentos e Assessor Financeiro Sênior.
Analise o perfil e o capital disponível do cliente abaixo e elabore uma recomendação de alocação de carteira clara, técnica e didática.

DADOS DO CLIENTE:
- Nome: ${cliente.nome}
- Saldo Disponível: ${cliente.saldo_formatado} (R$ ${cliente.saldo.toFixed(2)})
- Perfil de Risco: ${cliente.perfil}

PRODUTOS SELECIONADOS NO CATÁLOGO PARA ESTE PERFIL E ORÇAMENTO:
${produtosCompativeis.map(p => `- ${p.produto} | Aporte Mínimo: R$ ${p.minimo.toFixed(2)} | Rentabilidade Esperada: ${p.rentabilidade}`).join('\n')}

INSTRUÇÕES PARA O RELATÓRIO:
1. Faça uma saudação calorosa e personalizada ao cliente.
2. Explique a estratégia recomendada com base no perfil (${cliente.perfil}) e nos objetivos de preservação ou multiplicação de patrimônio.
3. Apresente uma sugestão percentual de divisão do capital entre os produtos listados.
4. Finalize com orientações práticas de próximos passos e um disclaimer regulatório prudente.`;

  resultados.push({
    json: {
      ...cliente,
      produtos_compativeis: produtosCompativeis,
      total_produtos_sugeridos: produtosCompativeis.length,
      prompt_llm: promptLLM
    }
  });
}

return resultados;

